def month_range(start: str, end: str) -> list[str]:
    y, m = map(int, start.split("-")); ey, em = map(int, end.split("-"))
    out = []
    while (y, m) <= (ey, em):
        out.append(f"{y:04d}-{m:02d}")
        m += 1
        if m == 13: y, m = y + 1, 1
    return out


def month_end_us(month: str) -> int:
    y, m = map(int, month.split("-"))
    if m == 12: nxt = dt.datetime(y + 1, 1, 1, tzinfo=dt.timezone.utc)
    else: nxt = dt.datetime(y, m + 1, 1, tzinfo=dt.timezone.utc)
    return int(nxt.timestamp() * 1_000_000)


